begin;
select plan(18);
select has_function('exam_delivery','package_v2_response_valid',array['text','jsonb','jsonb']);
select has_function('exam_delivery','score_package_v2_response',array['text','jsonb','jsonb','boolean']);
select ok(exam_delivery.package_v2_response_valid('true-false-single-v1','{}','{"answer":false}'),'boolean false is a valid explicit response');
select isnt(exam_delivery.package_v2_response_valid('true-false-single-v1','{}','{"answer":"false"}'),true,'boolean strings fail closed');
select ok(exam_delivery.package_v2_response_valid('true-false-composite-v1','{"statements":[{"id":"s1"},{"id":"s2"}]}','{"answer":{"s1":true}}'),'partial composite response is persistable');
select isnt(exam_delivery.package_v2_response_valid('true-false-composite-v1','{"statements":[{"id":"s1"}]}','{"answer":{"unknown":true}}'),true,'unknown statement is rejected');
select ok(exam_delivery.package_v2_response_valid('matching-v1','{"sources":[{"id":"s1"}],"targets":[{"id":"t1"}],"allowTargetReuse":false}','{"answer":{"s1":"t1"}}'),'matching identities validate');
select isnt(exam_delivery.package_v2_response_valid('matching-v1','{"sources":[{"id":"s1"}],"targets":[{"id":"t1"}]}','{"answer":{"s1":"unknown"}}'),true,'unknown matching target is rejected');
select isnt(exam_delivery.package_v2_response_valid('matching-v1','{"sources":[{"id":"s1"},{"id":"s2"}],"targets":[{"id":"t1"}],"allowTargetReuse":false}','{"answer":{"s1":"t1","s2":"t1"}}'),true,'duplicate target is rejected when reuse is disabled');
select ok(exam_delivery.package_v2_response_valid('code-dropdown-completion-v1','{"blanks":[{"id":"b1","options":[{"id":"o1"}]}]}','{"answer":{"b1":"o1"}}'),'dropdown identity validates');
select isnt(exam_delivery.package_v2_response_valid('code-dropdown-completion-v1','{"blanks":[{"id":"b1","options":[{"id":"o1"}]}]}','{"answer":{"b1":"wrong"}}'),true,'unknown dropdown option is rejected');
select is(exam_delivery.score_package_v2_response('true-false-single-v1','{"correctValue":false}','{"answer":false}',true)->>'status','Correct','false boolean scores correctly');
select is(exam_delivery.score_package_v2_response('true-false-composite-v1','{"correctValuesByStatement":{"s1":true,"s2":false}}','{"answer":{"s1":true}}',true),'{"earned":1,"maximum":2,"status":"Incomplete"}'::jsonb,'composite partial response reports incomplete raw score');
select is(exam_delivery.score_package_v2_response('true-false-composite-v1','{"correctValuesByStatement":{"s1":true,"s2":false}}','{"answer":{"s1":true,"s2":true}}',true),'{"earned":1,"maximum":2,"status":"Partial"}'::jsonb,'composite complete mixed result receives partial credit');
select is(exam_delivery.score_package_v2_response('matching-v1','{"correctTargetIdsBySource":{"s1":"t1","s2":"t2"}}','{"answer":{"s1":"t1","s2":"t1"}}',true),'{"earned":1,"maximum":2,"status":"Partial"}'::jsonb,'matching scores one point per pair');
select is(exam_delivery.score_package_v2_response('code-dropdown-completion-v1','{"correctOptionIdsByBlank":{"b1":"o1","b2":"o2"},"pointsByBlank":{"b1":1,"b2":2},"maximumRawPoints":3}','{"answer":{"b1":"o1","b2":"wrong"}}',true),'{"earned":1,"maximum":3,"status":"Partial"}'::jsonb,'dropdown scores approved raw points per blank');
select is(exam_delivery.score_package_v2_response('single-choice','{"correctOptionId":"a"}','{"answer":"a"}',true)->>'status','Correct','existing single-choice scoring remains compatible');
select is(exam_delivery.score_package_v2_response('reorder','{"correctItemIds":["a","b"]}','{"answer":["a","b"]}',true)->>'status','Correct','existing reorder scoring remains compatible');
select * from finish();
rollback;
